from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    background = freq.most_common(1)[0][0]

    best = None
    best_score = -1
    for color in range(10):
        if color == background:
            continue
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.65 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.65 * h]
        score = len(rows) * len(cols)
        if len(rows) >= 2 and len(cols) >= 2 and score > best_score:
            best = (color, rows, cols)
            best_score = score

    if best is None:
        return [[background]]

    line, rows, cols = best
    out = []
    for i in range(len(rows) - 1):
        row_out = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]
            ]
            if corners[0] != line and all(v == corners[0] for v in corners):
                row_out.append(corners[0])
            else:
                row_out.append(background)
        out.append(row_out)

    # Discard only all-background outer margins; preserve blank cells inside.
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    if out:
        while all(row[0] == background for row in out):
            for row in out:
                row.pop(0)
        while all(row[-1] == background for row in out):
            for row in out:
                row.pop()
    return out or [[background]]
